{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/shell-topbar.json
    The top bar of DashboardShell: the brand (when no sidebar carries it), the links (when there is no sidebar), an optional search field, and the signed-in person.
    Props (p): nav, brand, links, search, landmarkLabel. *}
{var $v_nav = ($p['nav'] ?? null)}
{var $v_brand = ($p['brand'] ?? 'show')}
{var $v_links = ($p['links'] ?? 'hide')}
{var $v_search = ($p['search'] ?? 'show')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if og_t(og_eq($v_brand, 'show'))}
    {capture $c_2}
      {=og_include('icons/LucideIcon.latte', ['name' => 'layers', 'size' => 24])|noescape}
      {capture $c_1}
        {=og_text(og_get($v_nav, ['brand']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'base', 'weight' => 'bold', 'class' => og_s((og_t(true) ? '' : 'sr-only')), 'children' => (string) $c_1])|noescape}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'class' => 'shrink-0', 'attrs' => og_attrs(['data-slot', 'brand']), 'children' => (string) $c_2])|noescape}
  {/if}
  {if og_t(og_and([og_eq($v_links, 'show'), og_gt(og_len(og_get($v_nav, ['links'])), 0)]))}
    {capture $c_7}
      {capture $c_6}
        {foreach og_l(og_get($v_nav, ['links'])) as $v_l}
          {capture $c_5}
            {capture $c_4}
              {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_l, ['icon'])), 'size' => 16])|noescape}
              {capture $c_3}
                {=og_text(og_get($v_l, ['name']))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => og_s((og_t(true) ? '' : 'sr-only')), 'children' => (string) $c_3])|noescape}
            {/capture}
            {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_l, ['href']), 'className' => og_cnv([og_cnv(['flex items-center gap-4 rounded py-2 text-sm', (og_t(true) ? 'px-4' : 'justify-center px-2'), (og_t(og_eq(og_get($v_l, ['id']), og_get($v_nav, ['current']))) ? 'bg-muted font-medium' : '')])]), 'current' => og_eq(og_get($v_l, ['id']), og_get($v_nav, ['current'])), 'size' => 'sm', 'testid' => 'item'], 'children' => og_markup($c_4)])|noescape}
          {/capture}
          {=og_include('compose/ListItem.latte', ['attrs' => og_attrs(['data-slot', 'links-row']), 'children' => (string) $c_5])|noescape}
        {/foreach}
      {/capture}
      {=og_include('compose/List.latte', ['class' => 'm-0 flex list-none items-center gap-2 p-0', 'children' => (string) $c_6])|noescape}
    {/capture}
    {=og_include('blocks/nav-block.latte', ['p' => ['label' => (og_t($v_landmarkLabel) ? og_uniq(og_tpl('{0}, {1}', [og_get($v_nav, ['label']), $v_landmarkLabel])) : og_get($v_nav, ['label'])), 'className' => og_cnv(['hidden lg:block'])], 'children' => og_markup($c_7)])|noescape}
  {/if}
  {if og_t(og_eq($v_search, 'show'))}
    {if og_t(og_eq($v_links, 'show'))}
      {capture $c_8}
        {=og_include('blocks/search-palette.latte', ['p' => ['label' => og_get($v_nav, ['search']), 'shortcut' => og_get($v_nav, ['shortcut'])]])|noescape}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => 'ml-auto hidden w-64 shrink-0 xl:block', 'children' => (string) $c_8])|noescape}
    {else}
      {=og_include('blocks/search-palette.latte', ['p' => ['label' => og_get($v_nav, ['search']), 'shortcut' => og_get($v_nav, ['shortcut'])]])|noescape}
    {/if}
  {/if}
  {capture $c_9}
    {=og_include('icons/LucideIcon.latte', ['name' => 'bell', 'size' => 20, 'class' => 'text-muted-foreground'])|noescape}
    {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_nav, ['userName']), 'ratio' => '1/1', 'className' => og_cnv(['size-8 shrink-0 rounded-full'])]])|noescape}
  {/capture}
  {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'center', 'class' => og_s((og_t(og_and([og_eq($v_links, 'show'), og_eq($v_search, 'show')])) ? 'shrink-0' : 'ml-auto shrink-0')), 'attrs' => og_attrs(['data-slot', 'user']), 'children' => (string) $c_9])|noescape}
{/capture}
{=og_include('compose/Block.latte', ['tag' => 'header', 'class' => 'flex h-16 shrink-0 items-center gap-6 border-b border-border bg-background px-6', 'attrs' => og_attrs(['aria-label', $v_landmarkLabel, 'data-slot', 'topbar']), 'children' => (string) $c_10])|noescape}
